function updateText(){ $('#count').textContent=String(state.word.length).padStart(2,'0');$('#word').textContent=state.word?[...state.word].slice(-36).map(g=>g===g.toUpperCase()?g:g.toUpperCase()+'⁻¹').join(' '):'∅ / an open beginning';$('#undo').disabled=busy||!state.steps.length;$('#clear').disabled=busy||!state.steps.length;document.querySelectorAll('[data-cross]').forEach(b=>b.disabled=busy);$('#demo').disabled=busy&&!demoRunning;}
