$('#listen').onclick=async()=>{stopDemo();if(on){on=false;audio.gate(false);$('#listen').classList.remove('active');$('#listen').innerHTML='Listen <span>↗</span>';$('#sound-status').textContent='Resting. Your weaving is kept.';}else try{await start();}catch(e){showError(e);}};
